SELECT unit_price_bucket, avg_quantity, stddev_unit_price FROM (SELECT CASE WHEN unit_price >= 400 THEN 'high' WHEN unit_price >= 90 THEN 'mid' ELSE 'low' END unit_price_bucket, ROUND(AVG(quantity), 2) avg_quantity, ROUND(STDDEV(unit_price), 2) stddev_unit_price FROM order_items GROUP BY CASE WHEN unit_price >= 400 THEN 'high' WHEN unit_price >= 90 THEN 'mid' ELSE 'low' END) x WHERE stddev_unit_price > 41 ORDER BY 2 DESC
